head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50600";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_keyword", fn: function () { return String((dma_pageContext.get("keyword") ?? "")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.list();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50600.onpageload' }); }
};

// [A] 초기 목록 미해결 — uldmgt50600: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'uldmgt50600.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_2_onsubmit
 * @description form_2 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_2_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50600.form_2_onsubmit' }); }
};

/**
 * @method
 * @name ipt_keyword_onkeyup
 * @description ipt_keyword 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_keyword_onkeyup = async function(e){
    try {
        await scwin.onEnter()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50600.ipt_keyword_onkeyup' }); }
};

/**
 * @method
 * @name img_98_onclick
 * @description img_98 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_98_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50600.img_98_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_list_xhr
 * @description list xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_list_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_list_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_list_xhr", unresolved: "action:self_submit:tx_list_xhr" };
};

/**
 * @method
 * @name tx_fn_replaceFormForm_xhr
 * @description replace Form Form xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_replaceFormForm_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_replaceFormForm_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_replaceFormForm_xhr", unresolved: "action:self_submit:tx_fn_replaceFormForm_xhr" };
};

/**
 * @method
 * @name tx_fn_restoreFormForm_xhr
 * @description restore Form Form xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_restoreFormForm_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_restoreFormForm_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_restoreFormForm_xhr", unresolved: "action:self_submit:tx_fn_restoreFormForm_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    scwin.form_listForm.action = "/filing/form.do";
    $c.util.getComponent('dma_listXhrReq').set('method', "findEmergencyFormList");
    await scwin.tx_list_xhr();
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseText responseText
 * @returns {void}
 * @hidden N
 */
scwin.onCompleteResponse = function (responseText) {
    ($c.util.getComponent('formListDiv') && $c.util.getComponent('formListDiv').setValue) ? $c.util.getComponent('formListDiv').setValue(responseText) : (($c.util.getComponent('formListDiv') && $c.util.getComponent('formListDiv').setText) ? $c.util.getComponent('formListDiv').setText(responseText) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'formListDiv'), void (responseText)));
};

/**
 * @method
 * @name search
 * @description search 처리
 * @param {*} orderBy orderBy
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function (orderBy) {
    if (orderBy != null) {
        const prevOrderBy = $c.util.getComponent('dma_listXhrReq').get('orderBy');
        $c.util.getComponent('dma_listXhrReq').set('orderBy', orderBy);
        if (prevOrderBy === orderBy) {
            const ascDiv = $c.util.getComponent('dma_listXhrReq').get('ascDiv');
            if (ascDiv === "asc") {
                $c.util.getComponent('dma_listXhrReq').set('ascDiv', "desc");
            } else {
                $c.util.getComponent('dma_listXhrReq').set('ascDiv', "asc");
            }
        } else {
            $c.util.getComponent('dma_listXhrReq').set('ascDiv', "asc");
        }
    } else {
        $c.util.getComponent('dma_listXhrReq').set('ascDiv', "asc");
    }
    $c.util.getComponent('dma_listXhrReq').set('pageIndex', 1);
    await scwin.list();
};

/**
 * @method
 * @name onEnter
 * @description on Enter 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onEnter = async function () {
    if (event.keyCode === 13) {
        await scwin.search();
    }
};

/**
 * @method
 * @name replaceFormForm
 * @description replace Form Form 처리
 * @param {String} formCd formCd
 * @param {String} formKorNm formKorNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.replaceFormForm = async function (formCd, formKorNm) {
    const _confirm = await $c.win.confirm("[" + formKorNm + "] 서식의 종목명을 수정가능하게 변경하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.util.getComponent('dma_listXhrReq').set('formCd', formCd);
    scwin.form_listForm.action = "/filing/updateForm.do";
    $c.util.getComponent('dma_listXhrReq').set('method', "replaceFormForm");
    await scwin.tx_fn_replaceFormForm_xhr();
    $c.win.setPageFrameSrc($c.win.getFrame(), null);
};

/**
 * @method
 * @name restoreFormForm
 * @description restore Form Form 처리
 * @param {String} formCd formCd
 * @param {String} formKorNm formKorNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.restoreFormForm = async function (formCd, formKorNm) {
    const _confirm = await $c.win.confirm("[" + formKorNm + "] 서식의 종목명 수정을 못하게 변경하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.util.getComponent('dma_listXhrReq').set('formCd', formCd);
    scwin.form_listForm.action = "/filing/updateForm.do";
    $c.util.getComponent('dma_listXhrReq').set('method', "restoreFormForm");
    await scwin.tx_fn_restoreFormForm_xhr();
    $c.win.setPageFrameSrc($c.win.getFrame(), null);
};
